package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class TypeBindings_toString_TriageGen1Test {

    @Test
    public void testToString_EmptyBindings() {
        // Testing the branch: if (_types.length == 0)
        TypeBindings bindings = TypeBindings.emptyBindings();
        assertEquals("<>", bindings.toString());
    }

    @Test
    public void testToString_SingleType() {
        // Testing the loop with one element and the condition (i > 0) being false
        JavaType mockType = mock(JavaType.class);
        when(mockType.getGenericSignature()).thenReturn("String");

        TypeBindings bindings = TypeBindings.create(Object.class, mockType);
        assertEquals("<String>", bindings.toString());
    }

    @Test
    public void testToString_MultipleTypes() {
        // Testing the loop with multiple elements and the condition (i > 0) being true (comma insertion)
        JavaType type1 = mock(JavaType.class);
        JavaType type2 = mock(JavaType.class);
        JavaType type3 = mock(JavaType.class);

        when(type1.getGenericSignature()).thenReturn("Integer");
        when(type2.getGenericSignature()).thenReturn("Boolean");
        when(type3.getGenericSignature()).thenReturn("List<String>");

        TypeBindings bindings = TypeBindings.create(Object.class, new JavaType[]{type1, type2, type3});

        // Expected format: <Type1,Type2,Type3>
        assertEquals("<Integer,Boolean,List<String>>", bindings.toString());
    }

    @Test
    public void testToString_WithNullSignature() {
        // Testing edge case where signature might be null (though unlikely in standard jackson usage)
        JavaType mockType = mock(JavaType.class);
        when(mockType.getGenericSignature()).thenReturn(null);

        TypeBindings bindings = TypeBindings.create(Object.class, mockType);
        assertEquals("<null>", bindings.toString());
    }
}
